import { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Heart, MessageCircle, ShoppingCart, Share2, Bookmark,
  MapPin, Zap, Package, MoreHorizontal, BadgeCheck,
} from "lucide-react";

const FEED_CATEGORIES = [
  { id: "all",         label: "সব",           emoji: "🏠" },
  { id: "electronics", label: "ইলেকট্রনিক্স", emoji: "📱" },
  { id: "fashion",     label: "ফ্যাশন",       emoji: "👗" },
  { id: "food",        label: "খাবার",         emoji: "🍔" },
  { id: "home",        label: "হোম & লিভিং",  emoji: "🏡" },
  { id: "wholesale",   label: "পাইকারি",       emoji: "📦" },
  { id: "services",    label: "সেবা",          emoji: "🔧" },
  { id: "beauty",      label: "বিউটি",         emoji: "💄" },
];

const mockProducts = [
  { id: "1", name: "ওয়্যারলেস হেডফোন প্রো", vendorName: "TechZone BD", location: "ঢাকা", price: 1299, category: "electronics", images: ["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&h=600&fit=crop"], description: "হাই-কোয়ালিটি সাউন্ড, নয়েজ ক্যান্সেলিং, ৩০ ঘণ্টা ব্যাটারি লাইফ।", rating: 4.5, reviewCount: 128, stock: 8 },
  { id: "2", name: "কোরিয়ান সিল্ক শাড়ি", vendorName: "Fashion Hub", location: "নারায়ণগঞ্জ", price: 3500, category: "fashion", images: ["https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=600&h=600&fit=crop"], description: "প্রিমিয়াম কোয়ালিটি সিল্ক শাড়ি, বিভিন্ন রঙে পাওয়া যাচ্ছে।", rating: 4.8, reviewCount: 312, stock: 15 },
  { id: "3", name: "স্মার্ট ওয়াচ সিরিজ ৫", vendorName: "GadgetWorld", location: "চট্টগ্রাম", price: 2499, category: "electronics", images: ["https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&h=600&fit=crop"], description: "হেলথ ট্র্যাকিং, GPS, ওয়াটারপ্রুফ স্মার্টওয়াচ।", rating: 4.2, reviewCount: 89, stock: 3 },
  { id: "4", name: "হোম ডেকোর সেট", vendorName: "LivingSpace", location: "রাজশাহী", price: 1800, category: "home", images: ["https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=600&h=600&fit=crop"], description: "আধুনিক ডিজাইনের হোম ডেকোর সেট, ঘর সাজানোর জন্য পারফেক্ট।", rating: 4.3, reviewCount: 67, stock: 20 },
];

const timeAgo = (i: number) => {
  const times = ["২ মিনিট আগে", "১৫ মিনিট আগে", "৩০ মিনিট আগে", "১ ঘণ্টা আগে"];
  return times[i % times.length];
};

function PostCard({ product, index }: { product: any; index: number }) {
  const navigate = useNavigate();
  const [liked, setLiked] = useState(false);
  const [saved, setSaved] = useState(false);
  const [saves, setSaves] = useState(Math.floor(Math.random() * 200) + 10);

  const compareAt = product.price ? Math.round(product.price * 1.18) : 0;
  const discount = product.price && compareAt > product.price
    ? Math.round(((compareAt - product.price) / compareAt) * 100) : 0;

  return (
    <article
      className="rounded-2xl overflow-hidden border"
      style={{ background: "var(--pm-surface)", borderColor: "var(--pm-border)", backdropFilter: "blur(14px)" }}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 pt-4 pb-3">
        <div className="flex items-center gap-3">
          <div
            className="h-10 w-10 rounded-xl flex items-center justify-center text-xs font-bold text-white shadow-md border border-white/10"
            style={{ background: "linear-gradient(135deg, var(--pm-blob1), var(--pm-blob2))" }}
          >
            {(product.vendorName || "V").slice(0, 2).toUpperCase()}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <span className="font-semibold text-sm" style={{ color: "var(--pm-text)" }}>
                {product.vendorName}
              </span>
              <BadgeCheck className="h-3.5 w-3.5 text-orange-400" />
            </div>
            <div className="flex items-center gap-1.5 text-[10px]" style={{ color: "var(--pm-text-muted)" }}>
              <MapPin className="h-2.5 w-2.5" style={{ color: "var(--pm-accent)" }} />
              {product.location} · {timeAgo(index)}
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            className="text-xs px-3 py-1 rounded-full border transition-all"
            style={{ borderColor: "var(--pm-border)", color: "var(--pm-text-muted)" }}
          >
            Follow
          </button>
          <button style={{ color: "var(--pm-text-muted)" }}>
            <MoreHorizontal className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Image */}
      <div className="relative overflow-hidden" style={{ aspectRatio: "1/1" }}>
        {product.images?.[0] ? (
          <img src={product.images[0]} alt={product.name} className="w-full h-full object-cover" loading="lazy" />
        ) : (
          <div className="w-full h-full flex items-center justify-center" style={{ background: "var(--pm-surface)" }}>
            <Package className="h-16 w-16" style={{ color: "var(--pm-text-muted)" }} />
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

        {discount > 0 && (
          <div className="absolute top-3 left-3 px-2.5 py-1 rounded-lg text-[10px] font-bold text-white bg-red-500">
            -{discount}% OFF
          </div>
        )}
        {product.stock != null && product.stock <= 10 && product.stock > 0 && (
          <div className="absolute top-3 right-3 px-2.5 py-1 rounded-lg text-[10px] font-semibold text-white bg-orange-500/90">
            মাত্র {product.stock}টি বাকি
          </div>
        )}
        <div className="absolute bottom-3 left-3 right-3">
          <h3 className="font-semibold text-white text-sm line-clamp-1 drop-shadow">{product.name}</h3>
        </div>
      </div>

      {/* Price + Description */}
      <div className="px-4 pt-3 pb-2">
        <p className="text-xs line-clamp-2 mb-2 leading-relaxed" style={{ color: "var(--pm-text-muted)" }}>
          {product.description}
        </p>
        <div className="flex items-center gap-2">
          <span className="text-lg font-bold" style={{ color: "var(--pm-accent)" }}>
            ৳{product.price?.toLocaleString()}
          </span>
          {compareAt > product.price && (
            <span className="text-xs line-through" style={{ color: "var(--pm-text-muted)" }}>
              ৳{compareAt.toLocaleString()}
            </span>
          )}
          <span
            className="text-[10px] ml-auto px-2 py-0.5 rounded-full border"
            style={{ borderColor: "var(--pm-border)", color: "var(--pm-text-muted)" }}
          >
            {product.category}
          </span>
        </div>
      </div>

      {/* Stats */}
      <div
        className="px-4 py-1.5 flex items-center gap-3 text-[11px] border-b"
        style={{ borderColor: "var(--pm-border)", color: "var(--pm-text-muted)" }}
      >
        <span>❤️ {saves} saves</span>
        <span>⭐ {product.rating?.toFixed(1) || "4.5"}</span>
        <span>📦 {product.reviewCount || 0} reviews</span>
      </div>

      {/* Action Buttons */}
      <div className="px-2 py-1 grid grid-cols-5 gap-0.5">
        {[
          { icon: Heart,        label: "Save",     active: liked, activeColor: "text-rose-400",   activeBg: "bg-rose-500/10",   onClick: () => { setLiked(l => { setSaves(s => l ? s - 1 : s + 1); return !l; }); } },
          { icon: MessageCircle,label: "Q&A",      active: false, activeColor: "",                activeBg: "",                 onClick: () => {} },
          { icon: ShoppingCart, label: "Cart",     active: true,  activeColor: "text-orange-400", activeBg: "bg-orange-500/10", onClick: () => {} },
          { icon: Share2,       label: "Share",    active: false, activeColor: "",                activeBg: "",                 onClick: () => {} },
          { icon: Bookmark,     label: "Wishlist", active: saved, activeColor: "text-purple-400", activeBg: "bg-purple-500/10", onClick: () => setSaved(s => !s) },
        ].map(btn => (
          <button
            key={btn.label}
            onClick={btn.onClick}
            className={`flex flex-col items-center gap-1 py-2 rounded-xl text-[10px] transition-all ${
              btn.active ? `${btn.activeColor} ${btn.activeBg}` : "hover:bg-white/5"
            }`}
            style={{ color: btn.active ? undefined : "var(--pm-text-muted)" }}
          >
            <btn.icon className="h-4 w-4" />
            <span>{btn.label}</span>
          </button>
        ))}
      </div>

      {/* Buy Now */}
      <div className="px-3 pb-3">
        <button
          onClick={() => navigate(`/product/${product.id}`)}
          className="w-full py-2.5 rounded-xl text-sm font-bold text-white transition-all hover:opacity-90 flex items-center justify-center gap-2"
          style={{ background: "var(--pm-accent)" }}
        >
          <Zap className="h-4 w-4" /> এখনই কিনুন
        </button>
      </div>
    </article>
  );
}

export default function HomeFeed() {
  const navigate = useNavigate();
  const [activeCategory, setActiveCategory] = useState("all");

  const filtered = activeCategory === "all"
    ? mockProducts
    : mockProducts.filter(p => p.category === activeCategory);

  return (
    <div className="min-h-screen">
      {/* Mode Toggle */}
      <div
        className="sticky z-30 border-b"
        style={{ top: "64px", background: "var(--pm-nav-bg)", backdropFilter: "blur(16px)", borderColor: "var(--pm-border)" }}
      >
        <div className="px-4 flex items-center h-11 gap-2">
          <div
            className="flex items-center p-1 rounded-full gap-0.5"
            style={{ background: "var(--pm-surface)", border: "1px solid var(--pm-border)" }}
          >
            <button
              className="flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-bold text-white"
              style={{ background: "var(--pm-accent)" }}
            >
              📰 ফিড
            </button>
            <button
              onClick={() => navigate("/shop")}
              className="flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-medium transition-all"
              style={{ color: "var(--pm-text-muted)" }}
            >
              🛍️ মার্কেটপ্লেস
            </button>
          </div>
        </div>
      </div>

      {/* Category Filter */}
      <div
        className="sticky z-20 border-b"
        style={{ top: "107px", background: "var(--pm-nav-bg)", backdropFilter: "blur(12px)", borderColor: "var(--pm-border)" }}
      >
        <div className="flex items-center gap-2 py-2 px-4 overflow-x-auto scrollbar-hide">
          {FEED_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className="flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-all shrink-0 border"
              style={
                activeCategory === cat.id
                  ? { background: "var(--pm-accent)", color: "#fff", borderColor: "var(--pm-accent)" }
                  : { background: "var(--pm-surface)", color: "var(--pm-text-muted)", borderColor: "var(--pm-border)" }
              }
            >
              {cat.emoji} {cat.label}
            </button>
          ))}
        </div>
      </div>

      {/* Feed */}
      <div className="py-4 px-4 max-w-lg mx-auto space-y-4">
        {filtered.length === 0 ? (
          <div className="text-center py-20" style={{ color: "var(--pm-text-muted)" }}>
            <Package className="h-12 w-12 mx-auto mb-3 opacity-30" />
            <p className="text-sm">এই category-তে এখন কোনো পোস্ট নেই</p>
          </div>
        ) : (
          filtered.map((product, i) => (
            <PostCard key={product.id} product={product} index={i} />
          ))
        )}

        {filtered.length > 0 && (
          <button
            className="w-full py-3 rounded-xl text-sm font-medium border transition-all"
            style={{ borderColor: "var(--pm-border)", color: "var(--pm-text-muted)", background: "var(--pm-surface)" }}
          >
            আরো পোস্ট দেখুন ↓
          </button>
        )}
      </div>
    </div>
  );
}